; 2546 : int emuCheckLanguageArgument(char* cmdLine, int defaultLang){
; 2547 :     int i;
; 2548 :     int lang;
; 2549 :     char* argument;
; 2550 :     
; 2551 :     for (i = 0; argument = extractToken(cmdLine, i); i++) {
; 2552 :         if (strcmp(argument, "/language") == 0) {
; 2553 :             argument = extractToken(cmdLine, ++i);
; 2554 :             if (argument == NULL) return defaultLang;
; 2555 :             lang = langFromName(argument, 0);
; 2556 :             return lang == EMU_LANG_UNKNOWN ? defaultLang : lang;
; 2557 :         }
; 2558 :     }
; 2559 : 
; 2560 :     return defaultLang;
; 2561 : }
