; 1727 : void* createScreenShot(int large, int* bitmapSize, int png)
; 1728 : {
; 1729 :     void* bitmap = NULL;
; 1730 : 
; 1731 :     int zoom = large ? 2 : 1;
; 1732 : 
; 1733 :     DWORD* bmBitsDst = malloc(zoom * zoom * WIDTH * HEIGHT * sizeof(UInt32));
; 1734 :     VideoPalMode palMode      = st.pVideo->palMode;
; 1735 :     int scanLinesEnable       = st.pVideo->scanLinesEnable;
; 1736 :     int colorSaturationEnable = st.pVideo->colorSaturationEnable;
; 1737 :     
; 1738 :     FrameBuffer* frameBuffer = frameBufferGetViewFrame();
; 1739 : 
; 1740 :     if (frameBuffer == NULL || frameBuffer->maxWidth <= 0 || frameBuffer->lines <= 0) {
; 1741 :         return NULL;
; 1742 :     }
; 1743 : 
; 1744 :     st.pVideo->palMode = VIDEO_PAL_FAST;
; 1745 :     st.pVideo->scanLinesEnable = 0;
; 1746 :     st.pVideo->colorSaturationEnable = 0;
; 1747 : 
; 1748 :     if (png) {
; 1749 :         videoRender(st.pVideo, frameBufferGetViewFrame(), 32, zoom, 
; 1750 :                     bmBitsDst, 0, zoom * WIDTH * sizeof(DWORD), 0);
; 1751 :     }
; 1752 :     else {
; 1753 :         videoRender(st.pVideo, frameBufferGetViewFrame(), 32, zoom, 
; 1754 :                     bmBitsDst + (zoom * HEIGHT - 1) * zoom * WIDTH, 
; 1755 :                     0, -1 * zoom * WIDTH * sizeof(DWORD), 0);
; 1756 :     }
; 1757 : 
; 1758 :     st.pVideo->palMode               = palMode;
; 1759 :     st.pVideo->scanLinesEnable       = scanLinesEnable;
; 1760 :     st.pVideo->colorSaturationEnable = colorSaturationEnable;
; 1761 : 
; 1762 :     if (bitmapSize != NULL) {
; 1763 :         bitmap = ScreenShot2(bmBitsDst, 320 * zoom, frameBuffer->maxWidth * zoom, 240 * zoom, bitmapSize, png);
; 1764 :     }
; 1765 :     else {
; 1766 :         ScreenShot3(pProperties, bmBitsDst, 320 * zoom, frameBuffer->maxWidth * zoom, 240 * zoom, png);
; 1767 :     }
; 1768 : 
; 1769 :     free(bmBitsDst);
; 1770 : 
; 1771 :     return bitmap;
; 1772 : }
