; 1662 : static void emuWindowDraw(int onlyOnVblank)
; 1663 : {      
; 1664 :     static void* lock = NULL;
; 1665 :     int rv = 0;
; 1666 : 
; 1667 :     if (lock == NULL) {
; 1668 :         lock = archSemaphoreCreate(1);
; 1669 :     }
; 1670 : 
; 1671 :     archSemaphoreWait(lock, -1);
; 1672 : 
; 1673 :     if (!st.enteringFullscreen && 
; 1674 :         (pProperties->video.driver == P_VIDEO_DRVDIRECTX_VIDEO || 
; 1675 :         (pProperties->video.driver == P_VIDEO_DRVDIRECTX_D3D) || 
; 1676 :         (pProperties->video.driver == P_VIDEO_DRVDIRECTX)))
; 1677 :     {
; 1678 : #define PRINT_RENDERING_TIME 0
; 1679 : #if PRINT_RENDERING_TIME
; 1680 :         LARGE_INTEGER	iCurrentTime;
; 1681 :         double fStartTime;
; 1682 :         if(QueryPerformanceCounter(&iCurrentTime))
; 1683 :             fStartTime = (long double) iCurrentTime.QuadPart;
; 1684 : #endif
; 1685 : 
; 1686 :         st.diplaySync |= onlyOnVblank;
; 1687 : 
; 1688 : 
; 1689 : 		if (pProperties->video.driver == P_VIDEO_DRVDIRECTX_D3D)
; 1690 : 			rv = D3DUpdateSurface(st.emuHwnd, st.pVideo, st.diplaySync, &pProperties->video.d3d);
; 1691 : 		else {
; 1692 : 			int param = 0;
; 1693 : 			if (pProperties->video.windowSize == P_VIDEO_SIZEX2) param = 1;
; 1694 : 			if (pProperties->video.windowSize == P_VIDEO_SIZEX3) param = 2;
; 1695 : 
; 1696 : 			rv = DirectXUpdateSurface(st.pVideo,
; 1697 : 				st.showMenu | st.showDialog || emulatorGetState() != EMU_RUNNING,
; 1698 : 				0, 0, getZoom(),
; 1699 : 				pProperties->video.horizontalStretch,
; 1700 : 				pProperties->video.verticalStretch,
; 1701 : 				st.diplaySync,
; 1702 : 				param);
; 1703 : 		}
; 1704 : 
; 1705 : #if PRINT_RENDERING_TIME
; 1706 :         {
; 1707 :             char output[1024];
; 1708 :             double t;
; 1709 :             LARGE_INTEGER	iFrequency;
; 1710 :             QueryPerformanceFrequency(&iFrequency);
; 1711 :             QueryPerformanceCounter(&iCurrentTime);
; 1712 :             t = (double) (iCurrentTime.QuadPart - fStartTime) / (double) iFrequency.QuadPart;
; 1713 :             sprintf(output, "Rendering time: %fms\n", t*1000.0f);
; 1714 :             OutputDebugString(output);
; 1715 :         }
; 1716 : #endif
; 1717 :         st.diplaySync = 0;
; 1718 :         if (rv) {
; 1719 :             st.frameCount++;
; 1720 :         }
; 1721 :     }
; 1722 :     st.diplayUpdated = rv;
; 1723 : 
; 1724 :     archSemaphoreSignal(lock);
; 1725 : }
