; 1647 :             r.right = appConfigGetInt("screen.normal.width", 640+320);
; 1648 :             r.bottom = appConfigGetInt("screen.normal.height", 480+240);
; 1649 :         }
; 1650 : 
; 1651 :         mouseEmuSetCaptureInfo(&r, &d);
; 1652 :     }
; 1653 : 
; 1654 :     emulatorResume();
; 1655 : 
; 1656 :     st.enteringFullscreen = 0;
; 1657 : 
; 1658 :     InvalidateRect(NULL, NULL, TRUE);
