; 2420 : static int videoTimeTotal = 0;
; 2421 : static int videoTimeIdle = 1;
; 2422 : 
; 2423 : UInt32 videoGetCpuUsage() {
; 2424 :     videoTimeAverage = 1000 * (videoTimeTotal - videoTimeIdle) / videoTimeTotal;
