; 2427 :         videoTimeAverage = 0;
; 2428 :     }
; 2429 : 
; 2430 :     videoTimeIdle  = 0;
; 2431 :     videoTimeTotal = 1;
; 2432 : 
; 2433 :     return videoTimeAverage;
; 2434 : }
