; 2567 :     HDC hdc;
; 2568 :     hdc = GetDC(GetDesktopWindow());
; 2569 :     return GetDeviceCaps(hdc, BITSPIXEL) * GetDeviceCaps(hdc, PLANES);
; 2570 : }
